R=Path(__file__).resolve().parents[1];O=R/'doc/research/possible-bodies';REC=R/'doc/space/ca-intro-review-2026-09-13'
M=R/'commons/maps/CA_Introduction';manifest=[]
def save(name,s):
 (O/name).write_bytes(s.encode());manifest.append('possible-bodies/'+name)
