data=json.loads((M/'map_data.json').read_text(encoding='utf-8'))
cells=[];labels=[]
for z,row in enumerate(data['layers']['structure']):
 for x,v in enumerate(row):
  c={'w':'#36494a','0':'#e5d4ce','1':'#ebe6d9','3':'#b1b2a7','4':'#939c94','5':'#708780'}.get(v,'#ebe6d9')
  cells.append(f'<rect x="{x*24}" y="{z*24}" width="23" height="23" fill="{c}"/>')
order={'ca_rule_explorer':('1','#a53d69'),'persian_rug':('2','#b4781f'),'line_network_ca':('3','#4669a3')}
for z,row in enumerate(data['layers']['interactables']):
 for x,t in enumerate(row):
  if not t.strip():continue
  n=t.split('#')[0].split(':')[0];v,c=order.get(n,('·','#586663'))
  labels.append(f'<g><title>{html.escape(n)}</title><circle cx="{x*24+12}" cy="{z*24+12}" r="10" fill="{c}"/><text x="{x*24+12}" y="{z*24+16}" text-anchor="middle" fill="white" font-size="13">{v}</text></g>')
svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 312 456" role="img" aria-label="Authored hall plan, nine retained placements">'+''.join(cells+labels)+'</svg>'
save('ca-introduction-plan.svg',svg)
for name in ['final','technical','critical','tutorial']:
 save('ca-introduction-'+name+'.md',(M/(name+'.md')).read_text(encoding='utf-8'))
